mapper.select:
SELECT p.id, p.name, p.gender, CASE p.gender WHEN 0 THEN '女' WHEN 1 THEN '男' ELSE '未知' END AS genderText, TIMESTAMPDIFF(YEAR, p.birth_date, CURDATE()) AS age, DATE_FORMAT(p.diagnosis_date, '%Y-%m-%d') AS diagnosisDate, (SELECT DATE_FORMAT(MAX(r.exam_date), '%m-%d') FROM exam_record r WHERE r.patient_id = p.id) AS lastExamDate, (SELECT COUNT(*) FROM exam_record r WHERE r.patient_id = p.id) AS totalExams, (SELECT COUNT(DISTINCT v.indicator_id) FROM exam_value v JOIN exam_record r ON v.record_id = r.id WHERE r.patient_id = p.id AND v.is_abnormal != 0) AS abnormalCount FROM patient p WHERE p.user_id = #{userId}
AND p.name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY p.updated_at DESC

mapper.update:
UPDATE patient
name = #{name}, gender = #{gender}, birth_date = #{birthDate}, diagnosis_date = #{diagnosisDate}, phone = #{phone}, notes = #{notes},
WHERE id = #{id}
